class Solution {
    struct Point {
        int x, y, id;
    };
public:
    std::vector<int> beautifulPair(std::vector<int>& nums1, std::vector<int>& nums2) {
        int n = nums1.size();
        std::map<std::pair<int, int>, std::vector<int>> pl;
        for (int i = 0; i < n; ++i) {
            pl[{nums1[i], nums2[i]}].push_back(i);
        }
        for (auto& [pt, ids] : pl) {
            if (ids.size() > 1) return {ids[0], ids[1]};
        }
        std::vector<Point> pts(n);
        for (int i = 0; i < n; ++i) pts[i] = {nums1[i], nums2[i], i};
        std::sort(pts.begin(), pts.end(), [](const Point& a, const Point& b) {
            return a.x < b.x;
        });
        auto dist = [](const Point& a, const Point& b) {
            return std::abs(a.x - b.x) + std::abs(a.y - b.y);
        };
        auto dfs = [&](auto& self, int l, int r) -> std::tuple<long long, int, int> {
            if (l >= r) return {LLONG_MAX, -1, -1};
            int mid = (l + r) / 2;
            int mid_x = pts[mid].x;
            auto [d1, i1, j1] = self(self, l, mid);
            auto [d2, i2, j2] = self(self, mid + 1, r);
            long long best_d = d1; int best_i = i1, best_j = j1;
            if (d2 < best_d || (d2 == best_d && std::pair{i2, j2} < std::pair{best_i, best_j})) {
                best_d = d2; best_i = i2; best_j = j2;
            }
            std::vector<Point> strip;
            for (int i = l; i <= r; ++i) {
                if (std::abs(pts[i].x - mid_x) <= best_d) {
                    strip.push_back(pts[i]);
                }
            }
            std::sort(strip.begin(), strip.end(), [](const Point& a, const Point& b) {
                return a.y < b.y;
            });
            int m = strip.size();
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    if (strip[j].y - strip[i].y > best_d) break;
                    long long d = dist(strip[i], strip[j]);
                    int pi = std::min(strip[i].id, strip[j].id);
                    int pj = std::max(strip[i].id, strip[j].id);
                    if (d < best_d || (d == best_d && std::pair{pi, pj} < std::pair{best_i, best_j})) {
                        best_d = d; best_i = pi; best_j = pj;
                    }
                }
            }
            return {best_d, best_i, best_j};
        };
        auto [_, pi, pj] = dfs(dfs, 0, n - 1);
        return {pi, pj};
    }
};

class Solution {
    static class Point {
        int x, y, id;
        Point(int x, int y, int id) { this.x = x; this.y = y; this.id = id; }
    }
    public int[] beautifulPair(int[] nums1, int[] nums2) {
        int n = nums1.length;
        java.util.Map<String, java.util.List<Integer>> pl = new java.util.HashMap<>();
        for (int i = 0; i < n; i++) {
            String key = nums1[i] + "," + nums2[i];
            pl.computeIfAbsent(key, k -> new java.util.ArrayList<>()).add(i);
        }
        for (java.util.List<Integer> ids : pl.values()) {
            if (ids.size() > 1) return new int[]{ids.get(0), ids.get(1)};
        }
        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++) pts[i] = new Point(nums1[i], nums2[i], i);
        java.util.Arrays.sort(pts, (a, b) -> Integer.compare(a.x, b.x));
        long[] res = dfs(pts, 0, n - 1);
        return new int[]{(int) res[1], (int) res[2]};
    }
    private long[] dfs(Point[] pts, int l, int r) {
        if (l >= r) return new long[]{Long.MAX_VALUE, -1, -1};
        int mid = (l + r) / 2;
        int midX = pts[mid].x;
        long[] left = dfs(pts, l, mid);
        long[] right = dfs(pts, mid + 1, r);
        long bestD = left[0]; int bestI = (int) left[1], bestJ = (int) left[2];
        if (right[0] < bestD || (right[0] == bestD && (right[1] < bestI || (right[1] == bestI && right[2] < bestJ)))) {
            bestD = right[0]; bestI = (int) right[1]; bestJ = (int) right[2];
        }
        java.util.List<Point> strip = new java.util.ArrayList<>();
        for (int i = l; i <= r; i++) {
            if (Math.abs(pts[i].x - midX) <= bestD) strip.add(pts[i]);
        }
        strip.sort((a, b) -> Integer.compare(a.y, b.y));
        int m = strip.size();
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                if (strip.get(j).y - strip.get(i).y > bestD) break;
                long d = Math.abs(strip.get(i).x - strip.get(j).x) + Math.abs(strip.get(i).y - strip.get(j).y);
                int pi = Math.min(strip.get(i).id, strip.get(j).id);
                int pj = Math.max(strip.get(i).id, strip.get(j).id);
                if (d < bestD || (d == bestD && (pi < bestI || (pi == bestI && pj < bestJ)))) {
                    bestD = d; bestI = pi; bestJ = pj;
                }
            }
        }
        return new long[]{bestD, bestI, bestJ};
    }
}

var beautifulPair = function(nums1, nums2) {
    const n = nums1.length;
    const pl = new Map();
    for (let i = 0; i < n; i++) {
        const key = `${nums1[i]},${nums2[i]}`;
        if (!pl.has(key)) pl.set(key, []);
        pl.get(key).push(i);
    }
    for (const ids of pl.values()) {
        if (ids.length > 1) return [ids[0], ids[1]];
    }
    const pts = [];
    for (let i = 0; i < n; i++) pts.push({ x: nums1[i], y: nums2[i], id: i });
    pts.sort((a, b) => a.x - b.x);
    function dfs(l, r) {
        if (l >= r) return [Infinity, -1, -1];
        const mid = (l + r) >> 1;
        const midX = pts[mid].x;
        const left = dfs(l, mid);
        const right = dfs(mid + 1, r);
        let [bestD, bestI, bestJ] = left;
        if (right[0] < bestD || (right[0] === bestD && (right[1] < bestI || (right[1] === bestI && right[2] < bestJ)))) {
            [bestD, bestI, bestJ] = right;
        }
        const strip = [];
        for (let i = l; i <= r; i++) {
            if (Math.abs(pts[i].x - midX) <= bestD) strip.push(pts[i]);
        }
        strip.sort((a, b) => a.y - b.y);
        const m = strip.length;
        for (let i = 0; i < m; i++) {
            for (let j = i + 1; j < m; j++) {
                if (strip[j].y - strip[i].y > bestD) break;
                const d = Math.abs(strip[i].x - strip[j].x) + Math.abs(strip[i].y - strip[j].y);
                const pi = Math.min(strip[i].id, strip[j].id);
                const pj = Math.max(strip[i].id, strip[j].id);
                if (d < bestD || (d === bestD && (pi < bestI || (pi === bestI && pj < bestJ)))) {
                    bestD = d;
                    bestI = pi;
                    bestJ = pj;
                }
            }
        }
        return [bestD, bestI, bestJ];
    }
    const [_, pi, pj] = dfs(0, n - 1);
    return [pi, pj];
};
